  "Orders = distinct sales orders per category; TOTAL is distinct across categories (a multi-category SO counts once). Qty = ordered quantity in the category's unit; Shipped reads invoiced. Picking and Fulfilled are this app's pick status; the rest is Zoho's CF.Status (Internal).": {
    en: "Orders = distinct sales orders per category; TOTAL is distinct across categories (a multi-category SO counts once). Qty = ordered quantity in the category's unit; Shipped reads invoiced. Picking and Fulfilled are this app's pick status; the rest is Zoho's CF.Status (Internal).",
    es: "Pedidos = ordenes de venta distintas por categoria; TOTAL es distinto entre categorias (una SO de varias categorias cuenta una vez). Cant. = cantidad pedida en la unidad de la categoria; Enviado lee lo facturado. Preparando y Cumplido son el estado de preparacion de esta app; el resto es el CF.Status (Internal) de Zoho.",
  },
