  "Execute records the move here, writes the new location onto the record, and pends the METRC Location Change file on Pending Data Uploads. METRC itself changes only when that file is uploaded. Everything stays under": { en: "Execute records the move here, writes the new location onto the record, and pends the METRC Location Change file on Pending Data Uploads. METRC itself changes only when that file is uploaded. Everything stays under", es: "Ejecutar registra el movimiento aqui, escribe la nueva ubicacion en el registro y deja pendiente el archivo de cambio de ubicacion de METRC en Cargas de datos pendientes. METRC solo cambia cuando ese archivo se sube. Todo queda bajo" },
  "Move it? This pends the METRC Location Change file; METRC changes only when that file is uploaded.": { en: "Move it? This pends the METRC Location Change file; METRC changes only when that file is uploaded.", es: "Moverlo? Esto deja pendiente el archivo de cambio de ubicacion de METRC; METRC cambia solo cuando ese archivo se sube." },
